import{_ as s,o as e,c as n,a2 as p}from"./chunks/framework.BZO4qERu.js";const h=JSON.parse('{"title":"多媒体 (Media)","description":"","frontmatter":{},"headers":[],"relativePath":"media.md","filePath":"media.md","lastUpdated":1669882888000}'),i={name:"media.md"};function t(l,a,c,d,o,u){return e(),n("div",null,[...a[0]||(a[0]=[p(`<h1 id="多媒体-media" tabindex="-1">多媒体 (Media)</h1><hr><p style="font:italic 1em sans-serif;color:#78909C;">此章节待补充或完善...</p><p style="font:italic 1em sans-serif;color:#78909C;">Marked by SuperMonster003 on Oct 22, 2022.</p><hr><p>media模块提供多媒体编程的支持. 目前仅支持音乐播放和媒体文件扫描. 后续会结合UI加入视频播放等功能.</p><p>需要注意是, 使用该模块播放音乐时是在后台异步播放的, 在脚本结束后会自动结束播放, 因此可能需要插入诸如<code>sleep()</code>的语句来使脚本保持运行. 例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//播放音乐</span></span>
<span class="line"><span>media.playMusic(&quot;/sdcard/1.mp3&quot;);</span></span>
<span class="line"><span>//让音乐播放完</span></span>
<span class="line"><span>sleep(media.getMusicDuration());</span></span></code></pre></div><h2 id="media-scanfile-path" tabindex="-1">media.scanFile(path)</h2><ul><li><code>path</code> {string} 媒体文件路径</li></ul><p>扫描路径path的媒体文件, 将它加入媒体库中；或者如果该文件以及被删除, 则通知媒体库移除该文件.</p><p>媒体库包括相册、音乐库等, 因此该函数可以用于把某个图片文件加入相册.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//请求截图</span></span>
<span class="line"><span>requestScreenCapture(false);</span></span>
<span class="line"><span>//截图</span></span>
<span class="line"><span>var im = captureScreen();</span></span>
<span class="line"><span>var path = &quot;/sdcard/screenshot.png&quot;;</span></span>
<span class="line"><span>//保存图片</span></span>
<span class="line"><span>im.saveTo(path);</span></span>
<span class="line"><span>//把图片加入相册</span></span>
<span class="line"><span>media.scanFile(path);</span></span></code></pre></div><h2 id="media-playmusic-path-volume-looping" tabindex="-1">media.playMusic(path[, volume, looping])</h2><ul><li><code>path</code> {string} 音乐文件路径</li><li><code>volume</code> {number} 播放音量, 为0~1的浮点数, 默认为1</li><li><code>looping</code> {boolean} 是否循环播放, 如果looping为<code>true</code>则循环播放, 默认为<code>false</code></li></ul><p>播放音乐文件path. 该函数不会显示任何音乐播放界面. 如果文件不存在或者文件不是受支持的音乐格式, 则抛出<code>UncheckedIOException</code>异常.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//播放音乐</span></span>
<span class="line"><span>media.playMusic(&quot;/sdcard/1.mp3&quot;);</span></span>
<span class="line"><span>//让音乐播放完</span></span>
<span class="line"><span>sleep(media.getMusicDuration());</span></span></code></pre></div><p>如果要循环播放音乐, 则使用looping参数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p>//传递第三个参数为true以循环播放音乐 media.playMusic(&quot;/sdcard/1.mp3&quot;, 1, true); //等待三次播放的时间 sleep(media.getMusicDuration() * 3);</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p>如果要使用音乐播放器播放音乐, 调用<code>app.viewFile(path)</code>函数.</p><h2 id="media-musicseekto-msec" tabindex="-1">media.musicSeekTo(msec)</h2><ul><li><code>msec</code> {number} 毫秒数, 表示音乐进度</li></ul><p>把当前播放进度调整到时间msec的位置. 如果当前没有在播放音乐, 则调用函数没有任何效果.</p><p>例如, 要把音乐调到1分钟的位置, 为<code>media.musicSeekTo(60 * 1000)</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//播放音乐</span></span>
<span class="line"><span>media.playMusic(&quot;/sdcard/1.mp3&quot;);</span></span>
<span class="line"><span>//调整到30秒的位置</span></span>
<span class="line"><span>media.musicSeekTo(30 * 1000);</span></span>
<span class="line"><span>//等待音乐播放完成</span></span>
<span class="line"><span>sleep(media.getMusicDuration() - 30 * 1000);</span></span></code></pre></div><h2 id="media-pausemusic" tabindex="-1">media.pauseMusic()</h2><p>暂停音乐播放. 如果当前没有在播放音乐, 则调用函数没有任何效果.</p><h2 id="media-resumemusic" tabindex="-1">media.resumeMusic()</h2><p>继续音乐播放. 如果当前没有播放过音乐, 则调用该函数没有任何效果.</p><h2 id="media-stopmusic" tabindex="-1">media.stopMusic()</h2><p>停止音乐播放. 如果当前没有在播放音乐, 则调用函数没有任何效果.</p><h2 id="media-ismusicplaying" tabindex="-1">media.isMusicPlaying()</h2><ul><li>返回 {boolean}</li></ul><p>返回当前是否正在播放音乐.</p><h2 id="media-getmusicduration" tabindex="-1">media.getMusicDuration()</h2><ul><li>返回 {number}</li></ul><p>返回当前音乐的时长. 单位毫秒.</p><h2 id="media-getmusiccurrentposition" tabindex="-1">media.getMusicCurrentPosition()</h2><ul><li>返回 {number}</li></ul><p>返回当前音乐的播放进度(已经播放的时间), 单位毫秒.</p>`,42)])])}const r=s(i,[["render",t]]);export{h as __pageData,r as default};
